-- ===========================================================================
--
-- One new table and one enum: a booking's copies of its shipping papers,
-- sea and air, inbound and outbound (sheet `Copy doc upload`, C16–C24):
--
--   House bill of lading · Master Bill of lading · CO · Commercial Invoice ·
--   Packing list · GSP · EXP · IGM · Delivery Order
--
-- Nothing existing is altered. The DDL was generated by `prisma migrate
-- diff`; the integrity, tenancy and audit statements below it are
-- hand-written.
-- ===========================================================================

-- CreateEnum
CREATE TYPE "copy_document_kind" AS ENUM ('HOUSE_BL', 'MASTER_BL', 'CO', 'COMMERCIAL_INVOICE', 'PACKING_LIST', 'GSP', 'EXP', 'IGM', 'DELIVERY_ORDER');

-- CreateTable
CREATE TABLE "copy_document" (
    "tenant_id" BIGINT NOT NULL,
    "id" BIGSERIAL NOT NULL,
    "shipment_id" BIGINT NOT NULL,
    "kind" "copy_document_kind" NOT NULL,
    "file_key" TEXT NOT NULL,
    "is_active" BOOLEAN NOT NULL DEFAULT true,
    "created_at" TIMESTAMPTZ(6) NOT NULL DEFAULT CURRENT_TIMESTAMP,
    "updated_at" TIMESTAMPTZ(6) NOT NULL,
    "created_by" BIGINT,
    "updated_by" BIGINT,
    "deleted_at" TIMESTAMPTZ(6),

    CONSTRAINT "copy_document_pkey" PRIMARY KEY ("id")
);

-- CreateIndex
CREATE INDEX "copy_document_tenant_id_idx" ON "copy_document"("tenant_id");

-- CreateIndex
CREATE INDEX "copy_document_shipment_id_idx" ON "copy_document"("shipment_id");

-- CreateIndex
CREATE UNIQUE INDEX "copy_document_tenant_id_id_key" ON "copy_document"("tenant_id", "id");

-- AddForeignKey
ALTER TABLE "copy_document" ADD CONSTRAINT "copy_document_tenant_id_fkey" FOREIGN KEY ("tenant_id") REFERENCES "tenant"("id") ON DELETE RESTRICT ON UPDATE CASCADE;

-- AddForeignKey
ALTER TABLE "copy_document" ADD CONSTRAINT "copy_document_shipment_id_fkey" FOREIGN KEY ("tenant_id", "shipment_id") REFERENCES "shipment"("tenant_id", "id") ON DELETE RESTRICT ON UPDATE CASCADE;

-- AddForeignKey
ALTER TABLE "copy_document" ADD CONSTRAINT "copy_document_created_by_fkey" FOREIGN KEY ("created_by") REFERENCES "user"("id") ON DELETE RESTRICT ON UPDATE CASCADE;

-- AddForeignKey
ALTER TABLE "copy_document" ADD CONSTRAINT "copy_document_updated_by_fkey" FOREIGN KEY ("updated_by") REFERENCES "user"("id") ON DELETE RESTRICT ON UPDATE CASCADE;



-- ---------------------------------------------------------------- integrity
-- One live copy per booking per document; uploading again replaces it.
CREATE UNIQUE INDEX "copy_document_one_live_key"
  ON "copy_document"("tenant_id", "shipment_id", "kind")
  WHERE "deleted_at" IS NULL;

-- ------------------------------------------------------------------ tenancy
ALTER TABLE "copy_document" ENABLE ROW LEVEL SECURITY;
CREATE POLICY tenant_isolation ON "copy_document"
  USING (tenant_id = app_staff_tenant())
  WITH CHECK (tenant_id = app_staff_tenant());

GRANT SELECT, INSERT, UPDATE ON TABLE "copy_document" TO ff_app;
GRANT USAGE, SELECT ON SEQUENCE "copy_document_id_seq" TO ff_app;

-- §4 rule 7: the audit trail is a trigger, so a write from any path is caught.
CREATE TRIGGER "copy_document_audit"
  AFTER INSERT OR UPDATE OR DELETE ON "copy_document"
  FOR EACH ROW EXECUTE FUNCTION app_audit_row();
